import { Router, type IRouter } from "express";
import { HealthCheckResponse } from "@workspace/api-zod";
import { getOpenAiApiKey, isOpenAiConfigured } from "../lib/openaiEnv.js";
import { llmConfigSummary, llmKeyPrefix } from "../lib/llmEnv.js";
import { getGeminiCallStats } from "../lib/llmChat.js";
import { getImageCompressStats } from "../lib/imageCompress.js";
import { getGeminiContextCacheStats } from "../lib/geminiContextCache.js";
import { getKommoSubdomain, isKommoConfigured } from "../lib/kommoEnv.js";
import { isAuthConfigured } from "../lib/authJwt.js";
import { getCatalogStatus } from "../services/catalogService.js";
import { getBuildMeta } from "../lib/buildMeta.js";
import { getLucyInfoStats } from "../services/lucyInfoStore.js";
import { getLucyInfoCachedDocs } from "../services/lucyInfoPriceCache.js";

const router: IRouter = Router();

router.get("/healthz", (_req, res) => {
  const data = HealthCheckResponse.parse({ status: "ok" });
  res.json(data);
});

// Endpoint detallado para keep-alive y diagnóstico externo
router.get("/health", async (_req, res) => {
  const llm = llmConfigSummary();
  const build = getBuildMeta();
  let lucy_info = { catalog: 0, tips: 0, total: 0 };
  try {
    lucy_info = await getLucyInfoStats();
  } catch {
    /* ignore — health debe responder igual */
  }
  res.json({
    status: "ok",
    timestamp: new Date().toISOString(),
    uptime: process.uptime(),
    service: "Lucy Bodasesor",
    version: build.version,
    lucy_prompt: build.lucy_prompt,
    built_at: build.built_at,
    built_at_display: build.built_at_display,
    features: [
      "understanding",
      "redaction-briefing",
      "training-db",
      "lucy-admin",
      "debounce-5s",
      "learning-from-human-chats",
      "learning-cron-keepalive",
      "learning-auto-approve-high-confidence",
      "silent-crm-watch",
      "emergency-contact-in-humano-trabaja",
      "knowledge-gaps-aprendizaje",
      "aprendizaje-panel-from-chats",
      "lucy-info-pdf-text",
      "llm-gemini-flash-lite",
      "gemini-vision-read-only",
      "gemini-voice-transcribe",
      "gemini-no-image-generation",
      "gemini-context-cache",
      "gemini-media-once",
      "gemini-image-compress-1024",
      "proveedor-alianza-handoff",
    ],
    learning: {
      note: "Panel /aprendizaje: chats, huecos Sheet e Información para Lucy (PDF→texto + tendencias). Sync Kommo; cron 5 min; auto-aprueba ≥0.85",
      cron_path: "/api/kommo/cron/learning",
      panel_path: "/aprendizaje",
      lucy_info_path: "/api/lucy-info",
    },
    lucy_info,
    lucy_info_cache: {
      docs: getLucyInfoCachedDocs().length,
      note: "Caché en memoria para inclusiones/precios PDF (seed o DB al arranque)",
    },
    silent_watch: {
      note: "En Humano Trabaja/Cotización/seguimientos Lucy no cotiza; actualiza CRM si cambian datos; solo escribe teléfonos de emergencia",
    },
    auth_configured: isAuthConfigured(),
    git_commit: build.git_commit,
    git_commit_short: build.git_commit_short,
    llm_provider: llm.provider,
    llm_model: llm.model,
    llm_configured: llm.configured,
    llm_key_prefix: llmKeyPrefix(),
    gemini_configured: llm.gemini_configured,
    openai_configured: isOpenAiConfigured(),
    openai_key_prefix: (() => {
      const key = getOpenAiApiKey();
      return key.startsWith("sk-") ? `${key.slice(0, 8)}…` : null;
    })(),
    voice_transcriber: llm.voice_transcriber,
    voice_whisper_fallback: llm.voice_whisper_fallback,
    voice_whisper_available: llm.voice_whisper_available,
    gemini_image_generation: llm.gemini_image_generation,
    gemini_allowed_model: llm.gemini_allowed_model,
    gemini_blocked_image_models: llm.gemini_blocked_image_models,
    gemini_call_stats: getGeminiCallStats(),
    gemini_context_cache: getGeminiContextCacheStats(),
    gemini_image_compress: getImageCompressStats(),
    gemini_policy:
      "Solo gemini-3.1-flash-lite (texto/visión/voz). Context cache del system. Media una sola vez. Imágenes ≤1024 JPEG. Sin Nano Banana/Imagen.",
    kommo_configured: isKommoConfigured(),
    kommo_subdomain: getKommoSubdomain() || null,
    lucy_outbound: {
      mode: "meta_wa_or_kommo_external",
      note: "WhatsApp → Meta API; Facebook/Instagram → Kommo talks/send_message; nota en timeline",
    },
    lucy_pipeline: "unified-v2",
    lucy_memory: {
      last_response_source: "cache_then_history_not_1048786",
      note: "Campo 1048786 = resumen interno CRM, no mensaje WhatsApp",
    },
    catalog: getCatalogStatus(),
  });
});

export default router;
